import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor w,
                                        c10::optional<torch::Tensor> b,
                                        int stride, int padding, int output_padding, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void __launch_bounds__(128, 8) conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bs,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K,
    int stride, int padding,
    int Dout, int Hout, int Wout,
    int groups, int Cin_per_group, int Cout_per_group,
    int tiles_per_group)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CoutPerBlock = 8;
  constexpr int CinChunk   = 8;
  constexpr int MAX_K      = 16;

  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int by  = blockIdx.y;
  const int g   = by / tiles_per_group;
  const int oc_tile_in_group = by % tiles_per_group;
  const int oc_base = g * Cout_per_group + oc_tile_in_group * CoutPerBlock;
  const int ic_base_group = g * Cin_per_group;
  const int P_total = Dout * Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;
  int64_t sXn = (int64_t)Cin * D * H * Win;
  int64_t sXc = (int64_t)D * H * Win;
  int64_t sXd = (int64_t)H * Win;
  int64_t sXh = (int64_t)Win;
  int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  int64_t sYc = (int64_t)Dout * Hout * Wout;
  int64_t sYd = (int64_t)Hout * Wout;
  int64_t sYh = (int64_t)Wout;
  int64_t sWci = (int64_t)Cout_per_group * K * K * K;
  int64_t sWco = (int64_t)K * K * K;
  int64_t sWkd = (int64_t)K * K;
  int64_t sWkh = (int64_t)K;
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                         make_shape(Cin, D, H, Win),
                         make_stride(sXc, sXd, sXh, (int64_t)1));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                         make_shape(Cout, Dout, Hout, Wout),
                         make_stride(sYc, sYd, sYh, (int64_t)1));
  auto mW = make_tensor(make_gmem_ptr(Wt),
                         make_shape(Cin, Cout_per_group, K, K, K),
                         make_stride(sWci, sWco, sWkd, sWkh, (int64_t)1));
  const int total_elems = CoutPerBlock * CinChunk * K * K * K;
  int64_t sSco = (int64_t)CinChunk * K * K * K;
  int64_t sSci = (int64_t)K * K * K;
  int64_t sSkd = (int64_t)K * K;
  int64_t sSkh = (int64_t)K;
  T* sW_buf0 = sW_ptr;
  T* sW_buf1 = sW_ptr + total_elems;
  auto make_sW = [&](T* base) {
    return make_tensor(make_smem_ptr(base),
                        make_shape(CoutPerBlock, CinChunk, K, K, K),
                        make_stride(sSco, sSci, sSkd, sSkh, (int64_t)1));
  };
  int  od_arr[PVec], oh_arr[PVec], ow_arr[PVec];
  bool pos_valid[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    if (p < P_total) {
      pos_valid[i] = true;
      int hw = Hout * Wout;
      int od = p / hw;
      int rem = p - od * hw;
      int oh = rem / Wout;
      int ow = rem - oh * Wout;
      od_arr[i] = od; oh_arr[i] = oh; ow_arr[i] = ow;
    } else {
      pos_valid[i] = false;
      od_arr[i] = 0; oh_arr[i] = 0; ow_arr[i] = 0;
    }
  }
  float acc[CoutPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CoutPerBlock; ++cc) {
    int oc_global = oc_base + cc;
    int oc_local  = oc_global - g * Cout_per_group;
    float bval = 0.0f;
    if (Bs != nullptr && oc_global < Cout && oc_local < Cout_per_group) {
      bval = (float)Bs[oc_global];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[cc][i] = bval;
  }
  auto load_chunk = [&](T* buf_ptr, int ic0_l, int chunkSize_l) {
    auto sWt_local = make_sW(buf_ptr);
    for (int idx = tid; idx < total_elems; idx += Threads) {
      int rem = idx;
      int kw = rem % K; rem /= K;
      int kh = rem % K; rem /= K;
      int kd = rem % K; rem /= K;
      int ci = rem % CinChunk; rem /= CinChunk;
      int cc = rem;
      int ic_global = ic0_l + ci;
      int oc_global = oc_base + cc;
      int oc_local  = oc_global - g * Cout_per_group;
      T wval = T(0);
      if (ci < chunkSize_l && ic_global < Cin && oc_local < Cout_per_group) {
        wval = mW(ic_global, oc_local, kd, kh, kw);
      }
      sWt_local(cc, ci, kd, kh, kw) = wval;
    }
  };
  int ic0 = ic_base_group;
  int ic_end = ic_base_group + Cin_per_group;
  int chunkSize0 = min(CinChunk, ic_end - ic0);
  load_chunk(sW_buf0, ic0, chunkSize0);
  __syncthreads();
  int cur_buf = 0;
  for (; ic0 < ic_end; ic0 += CinChunk) {
    int chunkSize = min(CinChunk, ic_end - ic0);
    T* cur_ptr = (cur_buf == 0) ? sW_buf0 : sW_buf1;
    T* nxt_ptr = (cur_buf == 0) ? sW_buf1 : sW_buf0;
    int next_ic0 = ic0 + CinChunk;
    bool has_next = next_ic0 < ic_end;
    if (has_next) {
      int nextChunkSize = min(CinChunk, ic_end - next_ic0);
      load_chunk(nxt_ptr, next_ic0, nextChunkSize);
    }
    auto sWt = make_sW(cur_ptr);
    for (int kd = 0; kd < K; ++kd) {
      int idv_arr[PVec];
      bool dvalid[PVec];
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        if (!pos_valid[i]) { dvalid[i] = false; idv_arr[i] = 0; continue; }
        int td = od_arr[i] + padding - kd;
        if (td % stride != 0) { dvalid[i] = false; idv_arr[i] = 0; continue; }
        int idv = td / stride;
        if (idv < 0 || idv >= D) { dvalid[i] = false; idv_arr[i] = 0; continue; }
        dvalid[i] = true;
        idv_arr[i] = idv;
      }
      for (int kh = 0; kh < K; ++kh) {
        int ihv_arr[PVec];
        bool hvalid[PVec];
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          if (!dvalid[i]) { hvalid[i] = false; ihv_arr[i] = 0; continue; }
          int th = oh_arr[i] + padding - kh;
          if (th % stride != 0) { hvalid[i] = false; ihv_arr[i] = 0; continue; }
          int ihv = th / stride;
          if (ihv < 0 || ihv >= H) { hvalid[i] = false; ihv_arr[i] = 0; continue; }
          hvalid[i] = true;
          ihv_arr[i] = ihv;
        }
        for (int kw = 0; kw < K; ++kw) {
          int iwv_arr[PVec];
          bool wvalid[PVec];
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            if (!hvalid[i]) { wvalid[i] = false; iwv_arr[i] = 0; continue; }
            int tw = ow_arr[i] + padding - kw;
            if (tw % stride != 0) { wvalid[i] = false; iwv_arr[i] = 0; continue; }
            int iwv = tw / stride;
            if (iwv < 0 || iwv >= Win) { wvalid[i] = false; iwv_arr[i] = 0; continue; }
            wvalid[i] = true;
            iwv_arr[i] = iwv;
          }
          bool any_valid = false;
          #pragma unroll
          for (int i = 0; i < PVec; ++i) any_valid = any_valid || wvalid[i];
          if (!any_valid) continue;
          for (int ci = 0; ci < chunkSize; ++ci) {
            int ic_global = ic0 + ci;
            float xval[PVec];
            #pragma unroll
            for (int i = 0; i < PVec; ++i) {
              xval[i] = wvalid[i] ? (float)mX(ic_global, idv_arr[i], ihv_arr[i], iwv_arr[i]) : 0.0f;
            }
            #pragma unroll
            for (int cc = 0; cc < CoutPerBlock; ++cc) {
              float wval = (float)sWt(cc, ci, kd, kh, kw);
              #pragma unroll
              for (int i = 0; i < PVec; ++i) {
                acc[cc][i] += xval[i] * wval;
              }
            }
          }
        }
      }
    }
    __syncthreads();
    cur_buf = 1 - cur_buf;
  }

  #pragma unroll
  for (int cc = 0; cc < CoutPerBlock; ++cc) {
    int oc_global = oc_base + cc;
    int oc_local  = oc_global - g * Cout_per_group;
    if (oc_global >= Cout || oc_local >= Cout_per_group) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!pos_valid[i]) continue;
      mY(oc_global, od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor w,
                                        c10::optional<torch::Tensor> b,
                                        int stride, int padding, int output_padding, int groups) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "tensors must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat, "expect float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N,C,D,H,W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, K, K, K]");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t D   = x_c.size(2);
  int64_t H   = x_c.size(3);
  int64_t Win = x_c.size(4);

  int64_t Cout_per_group = w_c.size(1);
  int64_t K = w_c.size(2);
  TORCH_CHECK(w_c.size(0) == Cin, "weight.size(0) must equal Cin");
  TORCH_CHECK(w_c.size(3) == K && w_c.size(4) == K, "kernel must be cubic");

  int64_t Cout = Cout_per_group * groups;
  int64_t Cin_per_group = Cin / groups;

  int64_t Dout = (D - 1) * stride - 2 * padding + K + output_padding;
  int64_t Hout = (H - 1) * stride - 2 * padding + K + output_padding;
  int64_t Wout = (Win - 1) * stride - 2 * padding + K + output_padding;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int Threads = 128;
  constexpr int PVec = 2;
  constexpr int CoutPerBlock = 8;
  constexpr int CinChunk = 8;

  int tiles_per_group = (int)((Cout_per_group + CoutPerBlock - 1) / CoutPerBlock);
  int64_t P_total = Dout * Hout * Wout;
  int64_t PTile = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)(groups * tiles_per_group),
      (unsigned)N
  );

  size_t shmem_bytes = (size_t)2 * CoutPerBlock * CinChunk * K * K * K * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose3d_kernel<float><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K,
      stride, padding,
      (int)Dout, (int)Hout, (int)Wout,
      groups, (int)Cin_per_group, (int)Cout_per_group,
      tiles_per_group
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with square kernel, implemented via a single
    custom CUDA kernel using CuTe tensors/layouts for indexing.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.groups = int(groups)
        self.has_bias = bool(bias)

        # Use a temporary nn.ConvTranspose3d purely to get PyTorch-consistent
        # parameter initialization (shapes & init distributions).
        temp = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )
        self.weight = nn.Parameter(temp.weight.data.clone())
        if bias:
            self.bias = nn.Parameter(temp.bias.data.clone())
        else:
            self.register_parameter("bias", None)

        self._ext = conv_transpose3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride, self.padding, self.output_padding, self.groups
        )

